import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { createClient as createServerClient } from "@/lib/supabase/server";
import { resolveUserId } from "@/lib/user-utils";
import { resolveUsername } from "@/lib/auth-helper";
import { tmdbGet } from "@/lib/tmdb";
import { anilistFetch } from "@/lib/anilist";

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
const supabase = createClient(supabaseUrl, supabaseKey);

const TMDB_IMAGE_BASE = "https://image.tmdb.org/t/p/w500";
const ANILIST_API = "https://graphql.anilist.co";

export async function GET(req: NextRequest) {
  const username = await resolveUsername(req);
  let activities: Activity[] = [];
  let userId: string | null = null;

  if (username) {
    userId = await resolveUserId(username);
    if (userId) {
      // Try to get real activities from follows
      const { data: follows } = await supabase
        .from("follows")
        .select("following_id")
        .eq("follower_id", userId);

      if (follows?.length) {
        const followingIds = follows.map((f) => f.following_id);
        const { data: followedUsers } = await supabase
          .from("users")
          .select("id, username")
          .in("id", followingIds);

        const idToUsername: Record<string, string> = {};
        for (const u of followedUsers || []) {
          idToUsername[u.id] = u.username;
        }

        const followingUsernames = Object.values(idToUsername);
        if (followingUsernames.length) {
          // Get real reviews
          const { data: reviews } = await supabase
            .from("reviews")
            .select("username, tmdb_id, media_type, content, rating, created_at, poster_url")
            .in("username", followingUsernames)
            .order("created_at", { ascending: false })
            .limit(30);

          // Get real tracking
          const { data: tracking } = await supabase
            .from("media_trackings")
            .select("username, tmdb_id, media_type, status, rating, updated_at, poster_url")
            .in("username", followingUsernames)
            .order("updated_at", { ascending: false })
            .limit(30);

          // Reviews
          for (const r of reviews || []) {
            if (r.rating && r.rating >= 5) {
              activities.push({
                id: `rev-${r.username}-${r.tmdb_id}`,
                type: "rated",
                username: r.username,
                tmdbId: r.tmdb_id,
                mediaType: r.media_type,
                title: "", poster: r.poster_url || null, year: null,
                rating: r.rating >= 10 ? r.rating / 10 : r.rating,
                content: r.content?.slice(0, 200),
                createdAt: r.created_at,
              });
            }
            if (r.content) {
              activities.push({
                id: `review-${r.username}-${r.tmdb_id}`,
                type: "review",
                username: r.username,
                tmdbId: r.tmdb_id,
                mediaType: r.media_type,
                title: "", poster: r.poster_url || null, year: null,
                content: r.content.slice(0, 200),
                rating: r.rating >= 10 ? r.rating / 10 : r.rating || undefined,
                createdAt: r.created_at,
              });
            }
          }

          // Tracking
          for (const t of tracking || []) {
            const typeMap: Record<string, string> = {
              completed: "watched",
              watching: "watching",
              plan_to_watch: "plan_to_watch",
            };
            const type = typeMap[t.status];
            if (!type) continue;
            activities.push({
              id: `track-${t.username}-${t.tmdb_id}`,
              type: type as Activity["type"],
              username: t.username,
              tmdbId: t.tmdb_id,
              mediaType: t.media_type,
              title: "", poster: t.poster_url || null, year: null,
              rating: t.rating || undefined,
              createdAt: t.updated_at,
            });
          }

          // Collections
          const { data: collections } = await supabase
            .from("user_lists")
            .select("id, user_id, name, published_at")
            .in("user_id", followingIds)
            .eq("is_published", true)
            .order("published_at", { ascending: false })
            .limit(20);

          if (collections?.length) {
            const listIds = collections.map((c: any) => c.id);
            const { data: itemCounts } = await supabase
              .from("list_items")
              .select("list_id")
              .in("list_id", listIds);
            const countMap: Record<string, number> = {};
            for (const li of (itemCounts || [])) {
              countMap[li.list_id] = (countMap[li.list_id] || 0) + 1;
            }
            for (const c of collections) {
              const resolvedUsername = idToUsername[c.user_id];
              if (!resolvedUsername) continue;
              activities.push({
                id: `col-${c.id}`,
                type: "collection",
                username: resolvedUsername,
                tmdbId: 0, mediaType: "",
                title: "", poster: null, year: null,
                collectionName: c.name,
                itemCount: countMap[c.id] || 0,
                createdAt: c.published_at,
              });
            }
          }
        }
      }
    }
  }


  // Sort, deduplicate, limit
  activities.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  // ─── PTW release check: scan user's plan_to_watch items for recent releases ───
  if (userId && username) {
    try {
      // Use the logged-in user's session client so RLS (auth.uid() = username)
      // lets us read this user's own plan_to_watch items. The global anon
      // client carries no session JWT → RLS returns an empty list → released
      // alerts for newly-premiered titles (e.g. Ted Lasso S4) never appear.
      const authDb = await createServerClient();
      const { data: ptwItems } = await authDb
        .from("media_trackings")
        .select("tmdb_id, media_type")
        .eq("username", userId)
        .eq("status", "plan_to_watch")
        .limit(50);
      
      if (ptwItems?.length) {
        const today = new Date();
        const recent = new Date(today);
        recent.setDate(recent.getDate() - 7); // last 7 days

        // Dedup by tmdb_id+media_type — one TMDB call per title
        const seenTmdb = new Set<string>();
        const uniqueItems: { tmdb_id: number; media_type: string }[] = [];
        for (const item of ptwItems) {
          const dedupKey = `${item.tmdb_id}-${item.media_type}`;
          if (!seenTmdb.has(dedupKey)) {
            seenTmdb.add(dedupKey);
            uniqueItems.push(item);
          }
        }
        
        for (const item of uniqueItems) {
          let releaseDate: Date | null = null;
          let title = "";
          let poster: string | null = null;
          let year: string | null = null;
          let season: number | null = null;
          
          try {
            if (item.media_type === "anime") {
              const res = await anilistFetch(`query($id:Int){Media(id:$id){title{english romaji}coverImage{extraLarge}startDate{year month day}seasonYear}}`, { id: item.tmdb_id });
              if (res.ok) {
                const j = await res.json();
                const m = j.data?.Media;
                if (m) {
                  title = m.title?.english || m.title?.romaji || "";
                  poster = m.coverImage?.extraLarge || null;
                  year = m.seasonYear?.toString() || null;
                  const sd = m.startDate;
                  if (sd?.year && sd?.month && sd?.day) {
                    releaseDate = new Date(sd.year, sd.month - 1, sd.day);
                  }
                }
              }
            } else {
              const ep = item.media_type === "tv" ? "tv" : "movie";
              const d = await tmdbGet(`/${ep}/${item.tmdb_id}`);
              title = d.title || d.name || "";
              poster = d.poster_path ? `${TMDB_IMAGE_BASE}${d.poster_path}` : null;
              // TV series "released" = when its LATEST SEASON PREMIERED. Airing weekly
              // episodes mid-season (e.g. X-Men '97 S2, which started 7/1) must NOT keep
              // re-triggering "released" every week — only the season premiere counts.
              // The season premiere date is the newest season's air_date (start date)
              // that has already arrived; season = that season's number.
              const todayStr = new Date().toISOString().slice(0, 10);
              let dateStr: string;
              let seasonAired: number | null = null;
              if (ep === "tv") {
                const airedSeasons = (d.seasons || [])
                  .filter((s: { season_number?: number; air_date?: string }) => s && s.season_number! > 0 && s.air_date && s.air_date <= todayStr)
                  .sort((a: { air_date?: string }, b: { air_date?: string }) => ((a.air_date || "") < (b.air_date || "") ? 1 : -1));
                if (airedSeasons.length) {
                  seasonAired = airedSeasons[0].season_number!;
                  dateStr = airedSeasons[0].air_date!; // season premiere date
                } else {
                  dateStr = "";
                }
              } else {
                dateStr = d.release_date || "";
              }
              year = dateStr.slice(0, 4) || null;
              if (ep === "tv" && seasonAired !== null) season = seasonAired;
              if (dateStr) {
                releaseDate = new Date(dateStr);
              }
            }
          } catch {}

          if (releaseDate && releaseDate >= recent && releaseDate <= today && title) {
            const key = `rel-${username}-${item.tmdb_id}`;
            if (!activities.find(a => a.id === key)) {
              activities.push({
                id: key,
                type: "released",
                username,
                tmdbId: item.tmdb_id,
                mediaType: item.media_type,
                title,
                poster,
                year,
                season,
                createdAt: releaseDate.toISOString(),
              });
            }
          }
        }
      }
    } catch {}
  }

  // ─── Notifications for the logged-in user: like/comment on their reviews ───
  // These surface as feed items ("X liked your review") so the feed shows more than
  // follow activity + PTW releases. They resolve by tmdb_id/media_type at enrich time.
  if (username) {
    try {
      // Use the session-aware client (carries the user's JWT) so RLS lets us read
      // this user's own notifications. The global anon/supabase client has no session.
      const authDb = await createServerClient();
      const { data: notifs } = await authDb
        .from("notifications")
        .select("*")
        .eq("target_username", username.trim().slice(0, 20))
        .in("type", ["like", "comment"])
        .order("created_at", { ascending: false })
        .limit(20);

      for (const n of notifs || []) {
        activities.push({
          id: `notif-${n.id}`,
          type: (n.type === "comment" ? "comment" : "like") as Activity["type"],
          username: n.actor_username || "",
          tmdbId: n.tmdb_id || 0,
          mediaType: n.media_type || "",
          title: n.title_name || "",
          poster: null,
          year: null,
          reviewId: n.review_id || null,
          targetUsername: n.target_username || null,
          notifRead: !!n.read,
          createdAt: n.created_at,
        });
      }
    } catch {
      // Notification fetch must never break the feed
    }
  }

  // Re-sort after adding released items
  activities.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  const seen = new Set<string>();
  const unique = activities.filter((a) => {
    const key = `${a.username}-${a.tmdbId}-${a.type}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, 20);

  // Enrich — skip fallback chains for items that already have poster_url
  const enriched = await Promise.all(
    unique.map(async (a) => {
      // released items already carry final title/year/season — don't clobber
      // year with first_air_date (would show "2020" for a 2026 season premiere).
      // like/comment notifications already carry their message in `title` — don't
      // let TMDB enrichment overwrite it with just the content title.
      if (a.type === "collection" || a.tmdbId === 0 || a.type === "released" || a.type === "like" || a.type === "comment") return a;
      
      // Already has poster from DB — just need title/year (fast single API call)
      if (a.poster) {
        try {
          if (a.mediaType === "anime") {
            const res = await anilistFetch(`query($id:Int){Media(id:$id){title{romaji english}seasonYear}}`, { id: a.tmdbId });
            if (res.ok) {
              const j = await res.json();
              const m = j.data?.Media;
              if (m) return { ...a, title: m.title?.english || m.title?.romaji || "", year: m.seasonYear?.toString() || null };
            }
          } else {
            const ep = a.mediaType === "tv" ? "tv" : "movie";
            const d = await tmdbGet(`/${ep}/${a.tmdbId}`);
            return { ...a, title: d.title || d.name || "", year: (d.release_date || d.first_air_date || "").slice(0, 4) || null };
          }
        } catch {}
        return a;
      }
      
      // No poster in DB — full enrichment chain
      if (a.mediaType === "anime") {
        const result = await enrichAnime(a.tmdbId);
        return { ...a, title: result.title || a.title, poster: result.poster, year: result.year || a.year };
      }
      const result = await enrichMovieTV(a.tmdbId, a.mediaType);
      return { ...a, title: result.title || a.title, poster: result.poster, year: result.year || a.year };
    })
  );

  return NextResponse.json({ activities: enriched });
}

// ─── Movie/TV poster resolution chain: TMDB → Wikipedia → Wikidata → TVMaze(TV) ───

async function enrichMovieTV(tmdbId: number, mediaType: string): Promise<{ title: string; poster: string | null; year: string | null }> {
  // 1. TMDB by ID
  let title = "";
  let year: string | null = null;
  try {
    const ep = mediaType === "tv" ? "tv" : "movie";
    const d = await tmdbGet(`/${ep}/${tmdbId}`);
    title = d.title || d.name || "";
    year = (d.release_date || d.first_air_date || "").slice(0, 4) || null;
    if (d.poster_path) {
      return { title, poster: `${TMDB_IMAGE_BASE}${d.poster_path}`, year };
    }
  } catch {}

  // 2. Wikipedia EN infobox poster
  if (title) {
    try {
      const wpPoster = await fetchWikipediaPoster(title);
      if (wpPoster) return { title, poster: wpPoster, year };
    } catch {}
  }

  // 3. Wikidata SPARQL → Wikipedia article → poster
  if (title) {
    try {
      const wpPoster = await fetchWikidataPoster(tmdbId, mediaType, title);
      if (wpPoster) return { title, poster: wpPoster, year };
    } catch {}
  }

  // 4. TVMaze (TV only)
  if (mediaType === "tv" && title) {
    try {
      const tvmPoster = await fetchTVMazePoster(title);
      if (tvmPoster) return { title, poster: tvmPoster, year };
    } catch {}
  }

  return { title, poster: null, year };
}

async function fetchWikipediaPoster(title: string): Promise<string | null> {
  const slugs = [
    title.replace(/\s+/g, "_").replace(/[^\w_-]/g, ""),
    title.replace(/\s+/g, "_") + "_(film)",
  ];
  for (const slug of slugs) {
    try {
      const res = await fetch(
        `https://en.wikipedia.org/w/api.php?action=parse&page=${encodeURIComponent(slug)}&prop=text&format=json&origin=*`,
        { headers: { "User-Agent": "Seriez/1.0" } }
      );
      if (!res.ok) continue;
      const data = await res.json();
      const text = data?.parse?.text?.["*"] || "";
      const m = text.match(/src="(\/\/upload\.wikimedia\.org\/wikipedia\/[^"]+\.(?:jpg|png|jpeg))"/i);
      if (m) {
        return "https:" + m[1].replace(/\/thumb\//, "/").replace(/\/\d+px-[^/]+$/, "");
      }
    } catch {}
  }
  return null;
}

async function fetchWikidataPoster(tmdbId: number, mediaType: string, _title: string): Promise<string | null> {
  try {
    const prop = mediaType === "tv" ? "P4983" : "P4947";
    const query = `SELECT ?article WHERE { ?item wdt:${prop} "${tmdbId}". ?article schema:about ?item; schema:isPartOf <https://en.wikipedia.org/>. } LIMIT 1`;
    const url = `https://query.wikidata.org/sparql?format=json&query=${encodeURIComponent(query)}`;
    const r = await fetch(url, { headers: { "User-Agent": "Seriez/1.0" } });
    if (!r.ok) return null;
    const j = await r.json();
    const article = j?.results?.bindings?.[0]?.article?.value;
    if (!article) return null;
    const wpTitle = article.replace("https://en.wikipedia.org/wiki/", "");
    // Extract poster from WP article
    const wpRes = await fetch(
      `https://en.wikipedia.org/w/api.php?action=parse&page=${encodeURIComponent(wpTitle)}&prop=text&section=0&format=json`,
      { headers: { "User-Agent": "Seriez/1.0" } }
    );
    if (!wpRes.ok) return null;
    const wpData = await wpRes.json();
    const text = wpData?.parse?.text?.["*"] || "";
    const m = text.match(/src="(\/\/upload\.wikimedia\.org\/wikipedia\/[^"]+\.(?:jpg|png|jpeg))"/i);
    if (m) {
      return "https:" + m[1].replace(/\/thumb\//, "/").replace(/\/\d+px-[^/]+$/, "");
    }
  } catch {}
  return null;
}

async function fetchTVMazePoster(title: string): Promise<string | null> {
  try {
    const r = await fetch(
      `https://api.tvmaze.com/singlesearch/shows?q=${encodeURIComponent(title)}`,
      { headers: { "User-Agent": "Seriez/1.0" } }
    );
    if (!r.ok) return null;
    const j = await r.json();
    const img = j?.image?.original || j?.image?.medium;
    return img || null;
  } catch {}
  return null;
}

async function enrichAnime(anilistId: number): Promise<{ title: string; poster: string | null; year: string | null }> {
  // 1. AniList GraphQL
  try {
    const res = await anilistFetch(`query($id:Int){Media(id:$id){idMal title{romaji english}coverImage{extraLarge}seasonYear}}`, { id: anilistId });
    if (res.ok) {
      const json = await res.json();
      const m = json.data?.Media;
      if (!m) return { title: "", poster: null, year: null };
      const title = m.title?.english || m.title?.romaji || "";
      const year = m.seasonYear?.toString() || null;

      // Got poster from AniList → done
      if (m.coverImage?.extraLarge) {
        return { title, poster: m.coverImage.extraLarge, year };
      }

      // No poster → try Jikan (using MAL id)
      if (m.idMal) {
        try {
          const jikanRes = await fetch(`https://api.jikan.moe/v4/anime/${m.idMal}`);
          if (jikanRes.ok) {
            const jd = await jikanRes.json();
            const jpg = jd?.data?.images?.jpg;
            if (jpg?.large_image_url) {
              return { title, poster: jpg.large_image_url, year };
            }
          }
        } catch {}
      }

      // Still no poster → try Kitsu
      if (title) {
        try {
          const kitsuRes = await fetch(
            `https://kitsu.io/api/edge/anime?filter[text]=${encodeURIComponent(title)}&page[limit]=1`,
            { headers: { "Accept": "application/vnd.api+json", "User-Agent": "Seriez/1.0" } }
          );
          if (kitsuRes.ok) {
            const kd = await kitsuRes.json();
            const pi = kd?.data?.[0]?.attributes?.posterImage;
            if (pi?.original) {
              return { title, poster: pi.original, year };
            }
          }
        } catch {}
      }

      // All sources exhausted — return without poster
      return { title, poster: null, year };
    }
  } catch {}

  // AniList failed — try Jikan directly (some AniList IDs happen to match MAL IDs)
  try {
    const jikanRes = await fetch(`https://api.jikan.moe/v4/anime/${anilistId}`);
    if (jikanRes.ok) {
      const jd = await jikanRes.json();
      const d = jd?.data;
      if (d) {
        return {
          title: d.title || "",
          poster: d.images?.jpg?.large_image_url || null,
          year: d.year?.toString() || null,
        };
      }
    }
  } catch {}

  // Nothing worked
  return { title: "", poster: null, year: null };
}

interface Activity {
  id: string;
  type: "review" | "rated" | "watched" | "watching" | "plan_to_watch" | "collection" | "released" | "like" | "comment";
  username: string;
  tmdbId: number;
  mediaType: string;
  title: string;
  poster: string | null;
  year: string | null;
  season?: number | null;
  rating?: number;
  content?: string;
  collectionName?: string;
  itemCount?: number;
  reviewId?: string | null;
  targetUsername?: string | null;
  notifRead?: boolean;
  createdAt: string;
}
